import type { ImageInfo } from "@lib/picture"

// Generated by scripts/gen-images.mjs (prebuild). Globbed so dev still works before it has run.
const manifest = Object.values(
	import.meta.glob<Record<string, ImageInfo>>("../data/image-manifest.json", { eager: true, import: "default" })
)[0] ?? {}

export const imageInfo = (src: string): ImageInfo | undefined => manifest[src]

export const withInfo = <T extends { src: string }>(image: T) => ({ ...image, info: imageInfo(image.src) })
